insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('ddaad405-7ef4-5ba5-a07c-3ff3738f259b', 'wg4-informative-writing-p04', (select id from public.skills where slug = 'write-g4-informative-writing'), null,
        '3-5', $q$A Library on Wheels$q$, $q$(1) Not everyone lives close to a library. (2) That is why some towns have a bookmobile. (3) A bookmobile is a large van or bus filled with books.

(4) A bookmobile has shelves along its inside walls. (5) It can hold thousands of books for children and adults. (6) Many bookmobiles also carry audiobooks and movies. (7) Some even have laptops that visitors can use.

(8) The bookmobile follows a schedule. (9) It parks at the same places on the same days each week. (10) It might stop at a park on Monday and a senior center on Tuesday. (11) People can borrow books there with their library cards. (12) Later, they return the books on the next visit.

(13) A bookmobile brings the library to people who cannot easily get to one.$q$, 'draft')
